1	package com.example.starter.service;
2	
3	import java.math.BigDecimal;
4	import java.time.Clock;
5	import java.time.Duration;
6	import java.time.Instant;
7	
8	import org.springframework.dao.DuplicateKeyException;
9	import org.springframework.stereotype.Service;
10	import org.springframework.transaction.annotation.Transactional;
11	
12	import com.example.starter.domain.ManifestStatus;
13	import com.example.starter.domain.WasteCategory;
14	import com.example.starter.repo.FacilityRepository;
15	import com.example.starter.repo.ManifestRepository;
16	import com.example.starter.repo.VehicleRepository;
17	import com.example.starter.support.BizException;
18	import com.example.starter.support.Fingerprints;
19	
20	/**
21	 * 进场称重与收运联单登记。
22	 * 皮重取车辆最近一次空车称重；超过 7 日未更新时须在同一事务内先复称皮重再登记联单。
23	 */
24	@Service
25	public class WeighingService {
26	
27	    /** 皮重有效期：超过 7 日未更新须复称。 */
28	    static final Duration TARE_VALIDITY = Duration.ofDays(7);
29	
30	    private final VehicleRepository vehicleRepository;
31	    private final FacilityRepository facilityRepository;
32	    private final ManifestRepository manifestRepository;
33	    private final Clock clock;
34	
35	    public WeighingService(VehicleRepository vehicleRepository,
36	                           FacilityRepository facilityRepository,
37	                           ManifestRepository manifestRepository,
38	                           Clock clock) {
39	        this.vehicleRepository = vehicleRepository;
40	        this.facilityRepository = facilityRepository;
41	        this.manifestRepository = manifestRepository;
42	        this.clock = clock;
43	    }
44	
45	    /**
46	     * 进场登记请求。tareKg 仅在皮重缺失或超过 7 日须复称时必填。
47	     */
48	    public record EntryCommand(
49	            String requestId,
50	            String plateNo,
51	            String community,
52	            String category,
53	            BigDecimal grossKg,
54	            String facilityCode,
55	            BigDecimal tareKg) {
56	    }
57	
58	    /**
59	     * 进场登记结果。
60	     *
61	     * @param reweighed 本次是否在同一事务内复称了皮重
62	     * @param replayed  是否为幂等重放（同键同参返回首次结果）
63	     */
64	    public record EntryResult(
65	            long manifestId,
66	            String requestId,
67	            String plateNo,
68	            String community,
69	            String category,
70	            BigDecimal grossKg,
71	            BigDecimal tareKg,
72	            BigDecimal netKg,
73	            String facilityCode,
74	            String status,
75	            boolean reweighed,
76	            boolean replayed,
77	            Instant createdAt) {
78	    }
79	
80	    @Transactional
81	    public EntryResult registerEntry(EntryCommand command) {
82	        validate(command);
83	        String fingerprint = fingerprintOf(command);
84	
85	        var existing = manifestRepository.findManifestByRequestId(command.requestId());
86	        if (existing.isPresent()) {
87	            return replayOrConflict(existing.get(), fingerprint, command.plateNo(), command.facilityCode());
88	        }
89	
90	        WasteCategory category = parseCategory(command.category());
91	        var vehicle = vehicleRepository.findByPlateNo(command.plateNo())
92	                .orElseThrow(() -> BizException.notFound("VEHICLE_NOT_FOUND", "车辆未登记：" + command.plateNo()));
93	        var facility = facilityRepository.findByCode(command.facilityCode())
94	                .filter(f -> f.active())
95	                .orElseThrow(() -> BizException.badRequest("FACILITY_NOT_IN_CATALOG",
96	                        "去向设施不在处理设施目录内：" + command.facilityCode()));
97	
98	        Instant now = clock.instant();
99	        BigDecimal tareKg;
100	        boolean reweighed;
101	        var latestTare = vehicleRepository.findLatestTare(vehicle.id());
102	        if (latestTare.isPresent()
103	                && !latestTare.get().weighedAt().isBefore(now.minus(TARE_VALIDITY))) {
104	            tareKg = latestTare.get().tareKg();
105	            reweighed = false;
106	        } else {
107	            if (command.tareKg() == null) {
108	                throw BizException.badRequest("TARE_REWEIGH_REQUIRED",
109	                        "皮重超过 7 日未更新或缺失，进场须先复称皮重");
110	            }
111	            if (command.tareKg().compareTo(BigDecimal.ZERO) <= 0) {
112	                throw BizException.badRequest("TARE_INVALID", "复称皮重必须为正数");
113	            }
114	            vehicleRepository.insertTare(vehicle.id(), command.tareKg(), now);
115	            tareKg = command.tareKg();
116	            reweighed = true;
117	        }
118	
119	        BigDecimal netKg = command.grossKg().subtract(tareKg);
120	        if (netKg.compareTo(BigDecimal.ZERO) == 0) {
121	            throw BizException.badRequest("NET_WEIGHT_ZERO", "净重恰等于 0，拒绝登记");
122	        }
123	        if (netKg.compareTo(BigDecimal.ZERO) < 0) {
124	            throw BizException.badRequest("NET_WEIGHT_NEGATIVE", "净重为负，毛重不得小于皮重");
125	        }
126	
127	        long manifestId;
128	        try {
129	            manifestId = manifestRepository.insertManifest(
130	                    command.requestId(), fingerprint, vehicle.id(), command.community(),
131	                    category.name(), command.grossKg(), tareKg, netKg,
132	                    facility.id(), ManifestStatus.IN_TRANSIT.name(), now);
133	        } catch (DuplicateKeyException e) {
134	            // 并发下唯一约束冲突：可能是同 requestId 幂等重试，也可能是同车已有执行中联单
135	            var duplicated = manifestRepository.findManifestByRequestId(command.requestId());
136	            if (duplicated.isPresent()) {
137	                return replayOrConflict(duplicated.get(), fingerprint, command.plateNo(), command.facilityCode());
138	            }
139	            throw BizException.conflict("VEHICLE_MANIFEST_IN_FLIGHT",
140	                    "同一车辆同时刻只允许一条执行中联单：" + command.plateNo());
141	        }
142	
143	        return new EntryResult(manifestId, command.requestId(), command.plateNo(), command.community(),
144	                category.name(), command.grossKg(), tareKg, netKg, facility.code(),
145	                ManifestStatus.IN_TRANSIT.name(), reweighed, false, now);
146	    }
147	
148	    private EntryResult replayOrConflict(ManifestRepository.ManifestRow row, String fingerprint,
149	                                         String plateNo, String facilityCode) {
150	        if (!row.fingerprint().equals(fingerprint)) {
151	            throw BizException.conflict("IDEMPOTENCY_CONFLICT",
152	                    "相同 requestId 提交了不同业务参数：" + row.requestId());
153	        }
154	        return new EntryResult(row.id(), row.requestId(), plateNo, row.community(), row.category(),
155	                row.grossKg(), row.tareKg(), row.netKg(), facilityCode, row.status(), false, true, row.createdAt());
156	    }
157	
158	    private static void validate(EntryCommand command) {
159	        if (command.grossKg() == null || command.grossKg().compareTo(BigDecimal.ZERO) <= 0) {
160	            throw BizException.badRequest("GROSS_INVALID", "毛重必须为正数");
161	        }
162	    }
163	
164	    private static WasteCategory parseCategory(String category) {
165	        try {
166	            return WasteCategory.valueOf(category);
167	        } catch (IllegalArgumentException | NullPointerException e) {
168	            throw BizException.badRequest("CATEGORY_INVALID", "未知垃圾品类：" + category);
169	        }
170	    }
171	
172	    private static String fingerprintOf(EntryCommand command) {
173	        return Fingerprints.of(
174	                command.requestId(),
175	                command.plateNo(),
176	                command.community(),
177	                command.category(),
178	                command.grossKg() == null ? "" : command.grossKg().stripTrailingZeros().toPlainString(),
179	                command.facilityCode(),
180	                command.tareKg() == null ? "" : command.tareKg().stripTrailingZeros().toPlainString());
181	    }
182	}
