3	import org.springframework.http.HttpStatus;
4	
5	/**
6	 * 业务异常：携带稳定错误码与 HTTP 状态，由全局异常处理器转换为响应体。
7	 */
8	public class BizException extends RuntimeException {
9	
10	    private final String code;
11	    private final HttpStatus status;
12	
13	    public BizException(String code, HttpStatus status, String message) {
14	        super(message);
15	        this.code = code;
16	        this.status = status;
17	    }
18	
19	    public String getCode() {
20	        return code;
21	    }
22	
23	    public HttpStatus getStatus() {
24	        return status;
