            String fingerprint,
            long vehicleId,
            String community,
            String category,
            BigDecimal grossKg,
            BigDecimal tareKg,
            BigDecimal netKg,
            long facilityId,
            int destinationVersion,
            String status,
            Instant createdAt) {
    }

    /**
     * 去向版本行：版本 1 为进场登记时的初始去向，其余为改投产生。
     */
