            long id,
            long manifestId,
            int version,
            long facilityId,
            String requestId,
            String fingerprint,
            Instant createdAt) {
    }

    /**
     * 回执行。
     *
     * @param facilityCode       回执声明的设施编码，旧式调用为 null
     * @param destinationVersion 回执声明的去向版本，旧式调用为 null
