        // 3. 在途改投 F-INCINERATION-2（去向版本 1 -> 2）
        mockMvc.perform(post("/api/manifests/{id}/reroutes", manifestId)
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("""
                                {
                                  "requestId": "REQ-API-RR-1",
